#include <bits/stdc++.h>
using namespace std;
int main() {
    int t;
    cin >> t;
    for (int test = 0; test < t; ++test) {
        int n;
        cin >> n;
        vector<int> p(1 << n);
        for (auto& e : p)
            cin >> e;
        auto solve = [&](auto&& solve, int l, int r) -> vector<int> {
            if (r - l == 1) return {p[l]};
            int mid = (l + r) / 2;
            vector<int> a = solve(solve, l, mid);
            vector<int> b = solve(solve, mid, r);
            if (a[0] > b[0]) swap(a, b);
            a.insert(a.end(), b.begin(), b.end());
            return a;
        };
        vector<int> ans = solve(solve, 0, 1 << n);
        for (int i = 0; i < (1 << n); ++i) {
            cout << ans[i] << " \n"[i == (1 << n) - 1];
        }
    }
}

#include <bits/stdc++.h>
using namespace std;

void solve() {
    int N;
    cin >> N;
    vector<int> P(1 << N);
    for (int i = 0; i < (1 << N); ++i) {
        cin >> P[i];
    }
    for (int b = N; b >= 1; --b) {
        for (int a = 0; a < (1 << (N - b)); ++a) {
            int l = a * (1 << b);
            int m = l + (1 << (b - 1));
            int r = l + (1 << b);
            int lmin = *min_element(P.begin() + l, P.begin() + m);
            int rmin = *min_element(P.begin() + m, P.begin() + r);
            if (lmin > rmin) {
                reverse(P.begin() + l, P.begin() + r);
            }
        }
    }
    for (int i = 0; i < (1 << N); ++i) {
        cout << P[i] << " \n"[i == (1 << N) - 1];
    }
}

int main() {
    int T;
    cin >> T;
    while (T--) solve();
}

use itertools::Itertools;
use proconio::input;

fn main() {
    input! {
        t: usize,
    }
    for _ in 0..t {
        input! {
            n: usize,
            mut p: [u32; 1 << n],
        }
        for b in 0..n {
            for a in (0..1 << n).filter(|&a| a & ((1 << (b + 1)) - 1) == 0) {
                if p[a] > p[a | 1 << b] {
                    for i in a..a | 1 << b {
                        p.swap(i, i | 1 << b);
                    }
                }
            }
        }
        println!("{}", p.iter().join(" "));
    }
}
